use hec_native_ic::{counted,instance::pick_instance,poly::Poly};
use std::collections::{BTreeSet,BTreeMap};
fn full(v:u16,g:usize)->u16{v|(((v.count_ones()%2)as u16)<<(2*g+1))}
fn project(mut v:u16,g:usize)->u16{assert_eq!(v.count_ones()%2,0);if(v>>(2*g))&1!=0{v^=(1u16<<(2*g+2))-1;}v&((1u16<<(2*g))-1)}
fn pairing(a:u16,b:u16,g:usize)->bool{(full(a,g)&full(b,g)).count_ones()%2==1}
fn action(v:u16,perm:&[usize],g:usize)->u16{let mask=full(v,g);let mut out=0;for(i,&j)in perm.iter().enumerate(){if(mask>>i)&1!=0{out|=1u16<<j;}}project(out,g)}
fn lagrangians(g:usize)->BTreeSet<Vec<u16>>{let mut spaces=BTreeSet::from([vec![0]]);for rank in 1..=g{let mut next=BTreeSet::new();for s in &spaces{for v in 1..1u16<<(2*g){if s.binary_search(&v).is_ok()||s.iter().any(|&w|pairing(v,w,g)){continue;}let mut t=s.clone();t.extend(s.iter().map(|w|w^v));t.sort_unstable();assert_eq!(t.len(),1<<rank);next.insert(t);}}eprintln!("ENUM genus={g} dimension={rank} spaces={}",next.len());spaces=next;}let expected:[usize;5]=[0,0,15,135,2295];assert_eq!(spaces.len(),expected[g]);for s in &spaces{assert_eq!(s.len(),1<<g);for &a in s{for &b in s{assert!(s.binary_search(&(a^b)).is_ok());assert!(!pairing(a,b,g));}}}spaces}
fn pair_kernels(g:usize)->BTreeSet<Vec<u16>>{fn visit(g:usize,remaining:Vec<usize>,pairs:&mut Vec<(usize,usize)>,out:&mut BTreeSet<Vec<u16>>){if remaining.is_empty(){let mut s=vec![0];for &(i,j)in pairs.iter(){let v=project((1<<i)|(1<<j),g);let mut t=s.clone();t.extend(s.iter().map(|w|w^v));t.sort_unstable();t.dedup();s=t;}assert_eq!(s.len(),1<<g);assert!(out.insert(s));return;}let i=remaining[0];for at in 1..remaining.len(){let j=remaining[at];let rest=remaining.iter().copied().filter(|&x|x!=i&&x!=j).collect();pairs.push((i,j));visit(g,rest,pairs,out);pairs.pop();}}let mut out=BTreeSet::new();visit(g,(0..2*g+2).collect(),&mut vec![],&mut out);assert_eq!(out.len(),[0,0,15,105,945][g]);out}
fn permutation(degrees:&[usize],g:usize)->Vec<usize>{let mut p:Vec<_>=(0..2*g+2).collect();let mut start=0;for &d in degrees{for i in 0..d{p[start+i]=start+(i+1)%d;}start+=d;}assert_eq!(start,2*g+1);p}
fn stable(s:&[u16],p:&[usize],g:usize)->bool{s.iter().all(|&v|s.binary_search(&action(v,p,g)).is_ok())}
fn main(){counted::disable();let mut all=BTreeMap::new();let mut paired=BTreeMap::new();for g in 2..=4{let l=lagrangians(g);let t=pair_kernels(g);assert!(t.iter().all(|s|l.contains(s)));let id:Vec<_>=(0..2*g+2).collect();assert!(l.iter().all(|s|stable(s,&id,g)));for a in 0..1u16<<(2*g){for b in 0..1u16<<(2*g){assert_eq!(project(full(a,g),g),a);assert_eq!(pairing(a,b,g),pairing(b,a,g));}}if g==2{let p=permutation(&[5],g);assert_eq!(l.iter().filter(|s|stable(s,&p,g)).count(),0);}if g==3{let p=permutation(&[7],g);assert_eq!(l.iter().filter(|s|stable(s,&p,g)).count(),2);assert_eq!(t.iter().filter(|s|stable(s,&p,g)).count(),0);let p=permutation(&[6,1],g);assert_eq!(t.iter().filter(|s|stable(s,&p,g)).count(),1);}all.insert(g,l);paired.insert(g,t);}
for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c.to_string(),v[2]);assert_eq!(inst.ell,ell);let c=inst.curve;assert_eq!(c.f.c[..c.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);assert_eq!(Poly::gcd(&c.f,&c.f.deriv(&c.fp),&c.fp).deg(),0);let n=2*g+1;let mut xp=Poly::x();let mut counts=vec![0usize;n+1];let mut fixed=vec![];for i in 1..=n{xp=xp.powmod(p,&c.f,&c.fp);let d=Poly::gcd(&c.f,&xp.sub(&Poly::x(),&c.fp),&c.fp).deg()as usize;let used=(1..i).filter(|j|i%j==0).map(|j|j*counts[j]).sum::<usize>();assert!(d>=used);assert_eq!((d-used)%i,0);counts[i]=(d-used)/i;fixed.push(d);}let mut degrees=vec![];for i in 1..=n{degrees.extend(std::iter::repeat_n(i,counts[i]));}assert_eq!(degrees.iter().sum::<usize>(),n);assert_eq!(fixed[0],(0..p).filter(|&x|c.f.eval(x,&c.fp)==0).count());for i in 1..=n{assert_eq!(fixed[i-1],degrees.iter().filter(|&&d|i%d==0).sum::<usize>());}let perm=permutation(&degrees,g);for a in 0..1u16<<(2*g){for b in 0..1u16<<(2*g){assert_eq!(action(a^b,&perm,g),action(a,&perm,g)^action(b,&perm,g));assert_eq!(pairing(action(a,&perm,g),action(b,&perm,g),g),pairing(a,b,g));}}let stable_all:Vec<_>=all[&g].iter().filter(|s|stable(s,&perm,g)).collect();let pair_count=stable_all.iter().filter(|s|paired[&g].contains(s.as_slice())).count();println!("CASE genus={g} p={p} c={} ell={ell} factor_degrees={degrees:?} fixed_roots={fixed:?} total_lagrangians={} rational_kernels={} pair_partition_kernels={pair_count} other_kernels={} permutation={perm:?}",inst.c,all[&g].len(),stable_all.len(),stable_all.len()-pair_count);for s in stable_all{println!("KERNEL genus={g} p={p} pair_partition={} abstract_vectors={s:?}",paired[&g].contains(s));}}
eprintln!("PASS models=11 exact_lagrangian_enumeration=true original_models=true pairing_action_checks=true controls_identity_five_cycle_seven_cycle=true no_quotient_or_target_transport_or_speed_claim=true");}
